{
  "version": "v1",
  "hooks": [
    {
      "name": "noskills-session-start",
      "description": "Generated by noskills: gives the agent the current noskills instruction.",
      "trigger": "SessionStart",
      "action": {
        "type": "command",
        "command": "npx eser@latest noskills invoke-hook session-start"
      },
      "timeout": 5
    },
    {
      "name": "noskills-pre-tool-use",
      "description": "Generated by noskills: refuses git writes, changes to the noskills settings and file edits the spec's phase does not allow.",
      "trigger": "PreToolUse",
      "matcher": "^(write|fs_write|fsWrite|fs_append|str_replace|delete_file|shell|execute_bash|execute_cmd)$",
      "action": {
        "type": "command",
        "command": "npx eser@latest noskills invoke-hook pre-tool-use"
      },
      "timeout": 30
    },
    {
      "name": "noskills-post-file-write",
      "description": "Generated by noskills: logs the files the agent changed.",
      "trigger": "PostToolUse",
      "matcher": "^(write|fs_write|fsWrite|fs_append|str_replace|delete_file)$",
      "action": {
        "type": "command",
        "command": "npx eser@latest noskills invoke-hook post-file-write"
      },
      "timeout": 3
    },
    {
      "name": "noskills-post-bash",
      "description": "Generated by noskills: logs the noskills commands the agent ran.",
      "trigger": "PostToolUse",
      "matcher": "^(shell|execute_bash|execute_cmd)$",
      "action": {
        "type": "command",
        "command": "npx eser@latest noskills invoke-hook post-bash"
      },
      "timeout": 3
    },
    {
      "name": "noskills-stop",
      "description": "Generated by noskills: records the iteration when the agent stops.",
      "trigger": "Stop",
      "action": {
        "type": "command",
        "command": "npx eser@latest noskills invoke-hook stop"
      },
      "timeout": 10
    }
  ]
}

